import httpx

def baca_status(client, jeda=time.sleep):
    for attempt in range(3):
        try:
            response = client.get("https://latihan.invalid/status")
            response.raise_for_status()
            data = response.json()
            if not isinstance(data, dict) or not isinstance(data.get("ok"), bool):
                raise ValueError("Kontrak response tidak sesuai")
            return data
        except (httpx.ConnectError, httpx.ConnectTimeout):
            if attempt == 2:
                raise
            jeda(0.1 * (2 ** attempt))

