import os
from hashlib import sha256
from secrets import token_urlsafe
from tempfile import TemporaryDirectory
from pathlib import Path
from typing import Literal
from contextlib import asynccontextmanager
from fastapi import FastAPI, Depends, HTTPException, Query, Response
from fastapi.security import HTTPBearer
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field, ConfigDict, model_validator
from sqlalchemy import (create_engine, MetaData, Table, Column, Integer, String,
                        Boolean, ForeignKey, CheckConstraint, select, insert, update, event)
from sqlalchemy.orm import Session

metadata = MetaData()
tiket = Table("tiket_aman", metadata,
    Column("id", Integer, primary_key=True),
    Column("judul", String(120), nullable=False),
    Column("owner_id", Integer, nullable=False),
    Column("status", String(20), nullable=False),
    Column("versi", Integer, nullable=False),
    Column("arsip", Boolean, nullable=False),
    CheckConstraint("status IN ('BARU', 'DIPROSES', 'SELESAI')"),
    CheckConstraint("versi > 0"))
audit = Table("audit_aman", metadata,
    Column("id", Integer, primary_key=True),
    Column("tiket_id", ForeignKey("tiket_aman.id"), nullable=False),
    Column("aktor_id", Integer, nullable=False),
    Column("aksi", String(30), nullable=False))

class Baru(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)
    judul: str = Field(min_length=1, max_length=120)
class Ubah(Baru):
    judul: str | None = Field(default=None, min_length=1, max_length=120)
    status: Literal["BARU", "DIPROSES", "SELESAI"] | None = None
    versi: int = Field(gt=0)
    @model_validator(mode="after")
    def ada_perubahan(self):
        if self.judul is None and self.status is None:
            raise ValueError("Isi judul atau status")
        return self

def digest(token):
    return sha256(token.encode()).hexdigest()

def create_app(database_url, registry):
    engine = create_engine(database_url)
    if engine.dialect.name == "sqlite":
        @event.listens_for(engine, "connect")
        def sqlite_fk(connection, record):
            connection.execute("PRAGMA foreign_keys=ON")
    metadata.create_all(engine)  # bootstrap database latihan baru
    @asynccontextmanager
    async def lifespan(app):
        yield
        engine.dispose()
    app = FastAPI(lifespan=lifespan)
    app.state.engine = engine
    bearer = HTTPBearer(auto_error=False)
    identities = {key: dict(value) for key, value in registry.items()}
    def current(credentials=Depends(bearer)):
        user = None if credentials is None else identities.get(digest(credentials.credentials))
        if user is None:
            raise HTTPException(401, "Token tidak diterima", headers={"WWW-Authenticate": "Bearer"})
        return user
    def db():
        with Session(engine) as session:
            yield session
    def visible(user):
        return True if user["role"] == "supervisor" else tiket.c.owner_id == user["id"]
    def get_row(session, id, user, archived=False):
        row = session.execute(select(tiket).where(tiket.c.id == id, tiket.c.arsip == archived, visible(user))).mappings().first()
        if row is None:
            raise HTTPException(404, "Tiket tidak ditemukan")
        return dict(row)
    def record(session, id, user, action):
        session.execute(insert(audit).values(tiket_id=id, aktor_id=user["id"], aksi=action))
    def change(session, old, user, values, action):
        result = session.execute(update(tiket).where(
            tiket.c.id == old["id"], tiket.c.versi == old["versi"],
            tiket.c.arsip == old["arsip"], visible(user)
        ).values(**values, versi=old["versi"] + 1))
        if result.rowcount != 1:
            raise HTTPException(409, "Konflik versi; baca ulang")
        record(session, old["id"], user, action)
    @app.post("/tiket", status_code=201)
    def create(data: Baru, session=Depends(db), user=Depends(current)):
        with session.begin():
            id = session.execute(insert(tiket).values(judul=data.judul, owner_id=user["id"], status="BARU", versi=1, arsip=False)).inserted_primary_key[0]
            record(session, id, user, "BUAT")
            return get_row(session, id, user)
    @app.get("/tiket")
    def listing(after_id: int = Query(0, ge=0), limit: int = Query(20, ge=1, le=100), session=Depends(db), user=Depends(current)):
        query = select(tiket).where(tiket.c.id > after_id, tiket.c.arsip == False, visible(user)).order_by(tiket.c.id).limit(limit)
        return [dict(row) for row in session.execute(query).mappings()]
    @app.get("/tiket/{id}")
    def detail(id: int, session=Depends(db), user=Depends(current)):
        return get_row(session, id, user)
    @app.patch("/tiket/{id}")
    def patch(id: int, data: Ubah, session=Depends(db), user=Depends(current)):
        with session.begin():
            old = get_row(session, id, user)
            if old["versi"] != data.versi:
                raise HTTPException(409, "Konflik versi; baca ulang")
            values = data.model_dump(exclude_none=True, exclude={"versi"})
            if data.status is not None and {"BARU": "DIPROSES", "DIPROSES": "SELESAI"}.get(old["status"]) != data.status:
                raise HTTPException(409, "Transisi status ditolak")
            change(session, old, user, values, "UBAH")
            return get_row(session, id, user)
    @app.delete("/tiket/{id}", status_code=204)
    def archive(id: int, versi: int = Query(gt=0), session=Depends(db), user=Depends(current)):
        with session.begin():
            old = get_row(session, id, user)
            if old["versi"] != versi or old["status"] != "BARU":
                raise HTTPException(409, "Versi atau status tidak sesuai")
            change(session, old, user, {"arsip": True}, "ARSIP")
        return Response(status_code=204)
    @app.post("/tiket/{id}/restore")
    def restore(id: int, versi: int = Query(gt=0), session=Depends(db), user=Depends(current)):
        if user["role"] != "supervisor":
            raise HTTPException(403, "Perlu supervisor")
        with session.begin():
            old = get_row(session, id, user, archived=True)
            if old["versi"] != versi:
                raise HTTPException(409, "Konflik versi; baca ulang")
            change(session, old, user, {"arsip": False}, "RESTORE")
            return get_row(session, id, user)
    @app.get("/tiket/{id}/riwayat")
    def history(id: int, session=Depends(db), user=Depends(current)):
        get_row(session, id, user)
        rows = session.execute(select(audit).where(audit.c.tiket_id == id).order_by(audit.c.id)).mappings()
        return [dict(row) for row in rows]
    return app

def create_local_app():
    # Isi lewat environment lokal; tidak ada fallback token bawaan.
    operator = os.environ["TOKEN_OPERATOR"]
    supervisor = os.environ["TOKEN_SUPERVISOR"]
    if min(len(operator), len(supervisor)) < 32 or operator == supervisor:
        raise ValueError("Gunakan dua token acak berbeda minimal 32 karakter")
    registry = {digest(operator): {"id": 10, "role": "operator"},
                digest(supervisor): {"id": 99, "role": "supervisor"}}
    return create_app(os.environ["DATABASE_URL"], registry)

