from datetime import datetime, timedelta, timezone
from secrets import token_urlsafe
from threading import Lock
from uuid import uuid4
import jwt
from pwdlib import PasswordHash
from fastapi import FastAPI, Depends, HTTPException, Response
from fastapi.security import HTTPBearer
from fastapi.testclient import TestClient
from pydantic import BaseModel, ConfigDict, Field

class Login(BaseModel):
    model_config = ConfigDict(extra="forbid")
    username: str = Field(min_length=1, max_length=80)
    password: str = Field(min_length=1, max_length=256)
class TokenOut(BaseModel):
    access_token: str
    token_type: str = "bearer"

ISSUER, AUDIENCE = "kursus-login", "kursus-api"
REQUIRED = ["sub", "jti", "iat", "nbf", "exp", "iss", "aud"]

def create_app(secret, users):
    if len(secret.encode()) < 32:
        raise ValueError("Gunakan secret acak minimal 32 byte")
    hasher = PasswordHash.recommended()
    dummy_hash = hasher.hash(token_urlsafe(32))
    users = {name: dict(data) for name, data in users.items()}
    sessions, lock = {}, Lock()
    bearer = HTTPBearer(auto_error=False)
    app = FastAPI()
    def denied():
        return HTTPException(401, "Kredensial tidak diterima", headers={"WWW-Authenticate": "Bearer"})
    def purge(now):
        for jti in [k for k, value in sessions.items() if value[1] <= now]:
            del sessions[jti]
    def current(credentials=Depends(bearer)):
        if credentials is None:
            raise denied()
        try:
            claims = jwt.decode(credentials.credentials, secret, algorithms=["HS256"],
                                issuer=ISSUER, audience=AUDIENCE,
                                options={"require": REQUIRED, "strict_aud": True})
        except jwt.InvalidTokenError:
            raise denied()
        user = users.get(claims["sub"])
        with lock:
            purge(int(datetime.now(timezone.utc).timestamp()))
            stored = sessions.get(claims["jti"])
        if user is None or user.get("disabled", False) or stored != (claims["sub"], claims["exp"]):
            raise denied()
        return claims
    @app.post("/login", response_model=TokenOut)
    def login(data: Login, response: Response):
        user = users.get(data.username)
        password_hash = user["password_hash"] if user else dummy_hash
        valid = hasher.verify(data.password, password_hash)
        if not valid or user is None or user.get("disabled", False):
            raise denied()
        now = datetime.now(timezone.utc)
        claims = {"sub": data.username, "jti": str(uuid4()), "iat": int(now.timestamp()),
                  "nbf": int(now.timestamp()), "exp": int((now + timedelta(minutes=5)).timestamp()),
                  "iss": ISSUER, "aud": AUDIENCE}
        with lock:
            purge(int(now.timestamp()))
            own = [key for key, value in sessions.items() if value[0] == data.username]
            if len(own) >= 5:
                del sessions[own[0]]
            sessions[claims["jti"]] = (claims["sub"], claims["exp"])
        response.headers["Cache-Control"] = "no-store"
        return {"access_token": jwt.encode(claims, secret, algorithm="HS256")}
    @app.get("/me")
    def me(claims=Depends(current)):
        return {"username": claims["sub"]}
    @app.post("/logout", status_code=204)
    def logout(claims=Depends(current)):
        with lock:
            sessions.pop(claims["jti"], None)
        return Response(status_code=204)
    return app

if __name__ == "__main__":
    password, secret = token_urlsafe(24), token_urlsafe(48)
    users = {"ana": {"password_hash": PasswordHash.recommended().hash(password)}}
    with TestClient(create_app(secret, users)) as client:
        r = client.post("/login", json={"username": "ana", "password": password})
        h = {"Authorization": "Bearer " + r.json()["access_token"]}
        print(r.status_code, client.get("/me", headers=h).json())
        print(client.post("/logout", headers=h).status_code)
        print(client.get("/me", headers=h).status_code)

import hmac
