# Protokol latihan: HMAC atas timestamp ASCII + titik + body mentah.
def sign(secret, timestamp, raw):
    return "sha256=" + hmac.new(secret, timestamp.encode("ascii") + b"." + raw, hashlib.sha256).hexdigest()

def verify(secret, timestamp, signature, raw, now):
    if not timestamp or len(timestamp) > 12 or not timestamp.isascii() or not timestamp.isdecimal():
        raise ValueError("Signature tidak diterima")
    if abs(now - int(timestamp)) > 300:
        raise ValueError("Signature tidak diterima")
    if not signature or len(signature) != 71:
        raise ValueError("Signature tidak diterima")
    expected = sign(secret, timestamp, raw)
    if not hmac.compare_digest(expected.encode("ascii"), signature.encode("ascii", errors="replace")):
        raise ValueError("Signature tidak diterima")

class Event(BaseModel):
    model_config = ConfigDict(extra="forbid")
    event_id: str = Field(min_length=1, max_length=64)
    pesan: str = Field(min_length=1, max_length=120)

def create_app(secret, clock=time.time):
    if len(secret) < 32:
        raise ValueError("Secret minimal 32 byte acak")
    app = FastAPI()
    @app.post("/webhook")
    async def webhook(request: Request):
        raw = bytearray()
        async for chunk in request.stream():
            if len(raw) + len(chunk) > 8192:
                raise HTTPException(413, "Body terlalu besar")
            raw.extend(chunk)
        try:
            verify(secret, request.headers.get("X-Timestamp"), request.headers.get("X-Signature"), bytes(raw), clock())
        except ValueError:
            raise HTTPException(401, "Signature tidak diterima")
        if request.headers.get("Content-Type", "").split(";")[0].strip().lower() != "application/json":
            raise HTTPException(415, "Gunakan application/json")
        try:
            event = Event.model_validate_json(raw)
        except ValidationError:
            raise HTTPException(422, "Format event tidak sesuai")
        return {"diterima": event.event_id}
    return app

