import os
import hmac
import hashlib
import json
import sqlite3
import time
from pathlib import Path
from tempfile import TemporaryDirectory
from secrets import token_bytes
from typing import Literal
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient
from pydantic import BaseModel, ConfigDict, Field, ValidationError, AwareDatetime
from starlette.concurrency import run_in_threadpool

def sign(secret, timestamp, raw):
    return "sha256=" + hmac.new(secret, timestamp.encode("ascii") + b"." + raw, hashlib.sha256).hexdigest()

def verify(secret, timestamp, signature, raw, now):
    if not timestamp or len(timestamp) > 12 or not timestamp.isascii() or not timestamp.isdecimal():
        raise ValueError("Signature ditolak")
    if abs(now - int(timestamp)) > 300 or not signature or len(signature) != 71:
        raise ValueError("Signature ditolak")
    if not hmac.compare_digest(sign(secret, timestamp, raw).encode("ascii"), signature.encode("ascii", errors="replace")):
        raise ValueError("Signature ditolak")

class Alarm(BaseModel):
    model_config = ConfigDict(extra="forbid")
    event_id: str = Field(min_length=1, max_length=64, pattern=r"^[A-Za-z0-9_-]+$")
    perangkat: str = Field(min_length=1, max_length=40, pattern=r"^[A-Za-z0-9_-]+$")
    jenis: Literal["RADIO_DOWN", "DAYA_RENDAH"]
    waktu: AwareDatetime

def create_app(path, sources, clock=time.time):
    sources = {key: {"secret": value["secret"], "perangkat": frozenset(value["perangkat"])} for key, value in sources.items()}
    if not sources or any(len(x["secret"]) < 32 or not x["perangkat"] for x in sources.values()):
        raise ValueError("Konfigurasi pengirim tidak lengkap")
    def connect():
        con = sqlite3.connect(path, timeout=1)
        con.execute("PRAGMA foreign_keys=ON")
        return con
    con = connect()
    try:
        with con:
            con.execute("CREATE TABLE IF NOT EXISTS tiket(id INTEGER PRIMARY KEY, pengirim TEXT NOT NULL, perangkat TEXT NOT NULL, jenis TEXT NOT NULL, waktu TEXT NOT NULL, status TEXT NOT NULL CHECK(status='BARU'))")
            con.execute("CREATE TABLE IF NOT EXISTS receipt(pengirim TEXT NOT NULL, event_id TEXT NOT NULL, fingerprint TEXT NOT NULL, body TEXT NOT NULL, tiket_id INTEGER NOT NULL REFERENCES tiket(id), PRIMARY KEY(pengirim,event_id))")
            con.execute("CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, tiket_id INTEGER NOT NULL REFERENCES tiket(id), aksi TEXT NOT NULL)")
    finally:
        con.close()
    app = FastAPI()
    def save(sender, alarm, fingerprint):
        con = connect()
        try:
            with con:
                con.execute("BEGIN IMMEDIATE")
                old = con.execute("SELECT fingerprint,body FROM receipt WHERE pengirim=? AND event_id=?", (sender, alarm.event_id)).fetchone()
                if old:
                    if old[0] != fingerprint:
                        raise HTTPException(409, "Event id dipakai untuk body berbeda")
                    return json.loads(old[1]), True
                id = con.execute("INSERT INTO tiket(pengirim,perangkat,jenis,waktu,status) VALUES (?,?,?,?,'BARU')",
                                 (sender, alarm.perangkat, alarm.jenis, alarm.waktu.isoformat())).lastrowid
                body = {"tiket_id": id, "status": "BARU"}
                con.execute("INSERT INTO receipt VALUES (?,?,?,?,?)", (sender, alarm.event_id, fingerprint, json.dumps(body), id))
                con.execute("INSERT INTO audit(tiket_id,aksi) VALUES (?,?)", (id, "ALARM_MASUK"))
            return body, False
        except sqlite3.OperationalError as exc:
            if getattr(exc, "sqlite_errorcode", None) == sqlite3.SQLITE_BUSY:
                raise HTTPException(503, "Database sibuk; ulangi event yang sama", headers={"Retry-After": "1"})
            raise
        finally:
            con.close()
    @app.get("/health/live")
    def live():
        return {"status": "ok"}
    @app.post("/webhooks/alarm", status_code=201)
    async def webhook(request: Request):
        raw = bytearray()
        async for chunk in request.stream():
            if len(raw) + len(chunk) > 8192:
                raise HTTPException(413, "Body terlalu besar")
            raw.extend(chunk)
        source_id = request.headers.get("X-Sender", "")
        source = sources.get(source_id)
        if source is None:
            raise HTTPException(401, "Signature tidak diterima")
        try:
            verify(source["secret"], request.headers.get("X-Timestamp"), request.headers.get("X-Signature"), bytes(raw), clock())
        except ValueError:
            raise HTTPException(401, "Signature tidak diterima")
        if request.headers.get("Content-Type", "").split(";")[0].strip().lower() != "application/json":
            raise HTTPException(415, "Gunakan application/json")
        try:
            alarm = Alarm.model_validate_json(raw)
        except ValidationError:
            raise HTTPException(422, "Format alarm tidak sesuai")
        if alarm.perangkat not in source["perangkat"]:
            raise HTTPException(403, "Perangkat bukan kewenangan pengirim")
        fingerprint = hashlib.sha256(raw).hexdigest()
        body, replayed = await run_in_threadpool(save, source_id, alarm, fingerprint)
        return JSONResponse(status_code=201, content=body, headers={"X-Replayed": str(replayed).lower()})
    return app

def create_local_app():
    secret = os.environ["ALARM_SECRET"].encode()
    devices = {x.strip() for x in os.environ["ALARM_DEVICES"].split(",") if x.strip()}
    return create_app(os.environ["ALARM_DB_PATH"], {"monitor-1": {"secret": secret, "perangkat": devices}})

